def table(d,rows,widths=None):
 t=d.add_table(rows=0, cols=len(rows[0]));t.alignment=WD_TABLE_ALIGNMENT.CENTER
 for ix,row in enumerate(rows):
  cells=t.add_row().cells
  for c,txt in zip(cells,row):
   c.text=txt;c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
   for par in c.paragraphs:
    par.paragraph_format.space_after=Pt(3)
    for run in par.runs:run.font.size=Pt(8.5);run.bold=(ix==0)
   tcPr=c._tc.get_or_add_tcPr();sh=OxmlElement('w:shd');sh.set(qn('w:fill'),'F0F0EF' if ix==0 else ('FFFFFF' if ix%2 else 'FAFAF9'));tcPr.append(sh)
 d.add_paragraph().paragraph_format.space_after=Pt(0)
 return t
